let state, selected, view='home';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusName={TODO:'ยังไม่เริ่ม',IN_PROGRESS:'กำลังทำ',WAITING:'รอการตอบกลับ',BLOCKED:'ติดขัด',REVIEW:'รอตรวจ',DONE:'เสร็จแล้ว'};
const option=(v,label,current)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label)}</option>`;
const badge=s=>`<span class="badge ${['BLOCKED','OVERDUE'].includes(s)?'bad':s==='AT RISK'?'warn':''}">${esc(statusName[s]||s)}</span>`;
function tell(s){$('#message').textContent=s;setTimeout(()=>$('#message').textContent='',5000)}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':state?.csrf||''},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok){const e=Error(result.error);e.status=r.status;throw e;}return result}
async function refresh(){try{state=await api('state');selected=state.projects.some(p=>p.id===selected)?selected:undefined;view='home';render()}catch(e){if(e.status===401)login();else tell(e.message)}}
function login(){state=null;torEdit=false;selected=undefined;$('#app').innerHTML=`<form class="card login" id="login"><span class="eyebrow">BD PMO / PROJECT CONTROL</span><h1>กลับมาทำงานต่อ</h1><p class="muted">สถานะ งานถัดไป และทีมของคุณในที่เดียว</p><label for="user">ชื่อผู้ใช้</label><input id="user" name="user" autocomplete="username" required><label for="password">รหัสผ่าน</label><input id="password" name="password" type="password" autocomplete="current-password" required><button class="primary">เข้าสู่ระบบ</button></form>`;$('#login').onsubmit=async e=>{e.preventDefault();try{await api('login',Object.fromEntries(new FormData(e.target)));await refresh()}catch(e){tell(e.message)}}}
function pnow(){return state.projects.find(p=>p.id===selected)}
function tasksHtml(tasks,p){return tasks.length?tasks.map(t=>`<div class="task"><div><h3>${esc(t.title)}</h3><p>${esc(t.owner)} · ${esc(t.due||'ยังไม่กำหนดวัน')} ${t.priority==='HIGH'?'· สำคัญมาก':''}</p><p class="muted">${esc(t.waiting||t.next||'เพิ่มขั้นตอนถัดไปเพื่อให้ทีมรับช่วงได้')}</p>${badge(t.status)}</div><button data-task="${t.id}" data-project="${p.id}">เปิดงาน</button></div>`).join(''):'<div class="empty">ไม่มีงานในรายการนี้</div>'}
function render(){const p=pnow();$('#app').innerHTML=`<aside><h2>BD PMO</h2><small>PROJECT OPERATIONS</small><nav class="nav-group"><span>WORKSPACE</span>${[['home','My Projects'],['overview','Overview']].map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${name}</button>`).join('')}</nav><details class="nav-group workflow-nav" ${['lifecycle','opening','procurement','planning','tor','acceptance','finance','risk','documents','closure','tasks','team'].includes(view)?'open':''}><summary>PROJECT WORKFLOW</summary>${[['lifecycle','Lifecycle checklist'],['opening','เริ่มงาน / สัญญา'],['procurement','จัดซื้อ / Vendor'],['planning','Planning'],['tor','TOR / ส่งมอบ'],['acceptance','ตรวจรับ'],['finance','การเงิน / รับ–จ่าย'],['risk','Risk / Issue'],['documents','Documents / Decisions'],['closure','ปิดโครงการ'],['tasks','Tasks / My Work'],['team','Team / Handover']].map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${name}</button>`).join('')}</details><nav class="nav-group"><span>PERSONAL</span>${[['my','My Work'],['inbox','การแจ้งเตือน'],...(state.isAdmin?[['admin','System Admin']]:[])].map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${name}</button>`).join('')}</nav><footer>${esc(state.user)}${state.isAdmin?' · ADMIN':''}<br><button id="logout">ออกจากระบบ</button></footer></aside><main class="${view==='lifecycle'?'workflow-page':''}"><header><div><span class="eyebrow">${selected?'PROJECT WORKSPACE':'HOME / MY PROJECTS'}</span><h1>${view==='my'?'งานของฉัน':view==='inbox'?'การแจ้งเตือน':view==='admin'?'System Admin':selected?esc(p?.name||'โครงการ'):'โครงการของฉัน'}</h1></div><div class="row"><select class="project-select" aria-label="เลือกโครงการ" id="projectSelect"><option value="">Home / My Projects</option>${state.projects.map(x=>option(x.id,x.name,selected)).join('')}</select>${!selected?'<button id="newProject">+ โครงการใหม่</button>':''}</div></header><div id="content"></div></main>`;
const content=$('#content');
if(view==='inbox'){content.innerHTML=`<div class="card">${state.notifications.length?state.notifications.map(n=>`<div class="task"><div>${esc(n.text)}<p class="muted">${esc(state.projects.find(p=>p.id===n.project)?.name)}</p></div><button data-notice="${n.id}" ${n.seen?'disabled':''}>${n.seen?'อ่านแล้ว':'ทำเครื่องหมายอ่านแล้ว'}</button></div>`).join(''):'<div class="empty">ยังไม่มีการแจ้งเตือนใหม่</div>'}</div>`}
else if(view==='my'){content.innerHTML=myWorkView()}
else if(view==='admin'&&state.isAdmin){content.innerHTML=adminView()}
else if(view==='home'){content.innerHTML=homeDashboard()}
 else if(view==='overview'){content.innerHTML=homeView(p)}
else if(!p){content.innerHTML='<div class="card empty"><h2>สร้างโครงการแรก</h2><p>เริ่มจากชื่อโครงการ แล้วเพิ่มสมาชิกและงานที่ต้องทำต่อ</p></div>'}
else if(view==='team'){content.innerHTML=teamView(p)}
 else if(view==='tasks'){content.innerHTML=`<div class="card"><div class="row"><h2>งานทั้งหมด · ${p.tasks.length}</h2>${p.role!=='VIEWER'&&!p.completed?'<button id="addTask" class="primary">+ เพิ่มงาน</button>':''}</div>${tasksHtml(p.tasks,p)}</div>`}
else if(view==='tor'){content.innerHTML=torView(p)}
else if(view==='planning'){content.innerHTML=planningView(p)}
else if(view==='lifecycle'){content.innerHTML=lifecycleView(p)}
else if(view==='acceptance'){content.innerHTML=acceptanceView(p)}
else if(state.controlModules?.[view]){content.innerHTML=controlView(p,view)}
else {content.innerHTML=homeView(p)}
wire();}
function eventSummary(e){const d=JSON.parse(e.detail);if(e.action==='crisis_handover')return d.after?.active?`เปิด/อัปเดต Crisis Handover · ผู้รับช่วง ${d.after.actingOwner||'—'}`:'ปิด Crisis Handover';if(e.action==='crisis_accept')return 'ผู้รับช่วงยืนยันรับช่วงโครงการแล้ว';if(e.action.startsWith('milestone_')||e.action==='project_info')return torEvent(e);if(e.action==='checklist')return `Checklist ${d.id}: ${statusName[d.before?.status]||'ยังไม่บันทึก'} → ${statusName[d.after?.status]||''}`;return d.title||d.text||d.name||(d.user?`${d.user}: ${d.before||'ใหม่'} → ${d.after}`:'')}
const milestoneStatusName={'':'ยังไม่ระบุ',NOT_DUE:'ยังไม่ถึงกำหนด',IN_PROGRESS:'กำลังดำเนินการ',READY:'พร้อมส่งมอบ',DELIVERED:'ส่งมอบแล้ว',WAITING_REPLY:'รอหนังสือตอบกลับ',WAITING_ACCEPTANCE:'รอตรวจรับ',ACCEPTED:'ตรวจรับแล้ว',LATE:'ล่าช้า',BLOCKED:'ติดปัญหา'};
let torEdit=false;
function infoCell(label,value){return `<div class='info-cell'><small>${esc(label)}</small><strong>${esc(value||'—')}</strong></div>`}
function money(v){if(v==null)return 'ยังไม่ระบุมูลค่าสัญญา';return new Intl.NumberFormat('th-TH',{style:'currency',currency:'THB',maximumFractionDigits:2}).format(Number(v||0))}
function num(v){return new Intl.NumberFormat('th-TH',{maximumFractionDigits:4}).format(Number(v||0))}
function torEvent(e){const d=JSON.parse(e.detail);if(e.action==='milestone_header')return `เปลี่ยนหัวคอลัมน์ ${d.field}: ${d.before||'—'} → ${d.after||'—'}`;if(e.action==='milestone_details')return 'แก้สถานะ / ผู้รับผิดชอบ / การส่งต่องวดงาน';if(e.action==='milestone_cell')return `งวดงาน ${d.workNo||''} · ${d.field}: ${d.before??'—'} → ${d.after??'—'}${d.reason?' · '+d.reason:''}`;return e.action==='project_info'?'แก้ข้อมูลสัญญา':e.action==='milestone_add'?'เพิ่มงวดงาน':'ลบงวดงาน'}
function legacyTorView(p){const i=p.projectInfo||{},s=p.paymentSummary||{};return `<section class='card'><div class='row'><div><h2>ข้อมูลโครงการ / สัญญา</h2><p class='muted'>ข้อมูลอ้างอิงหลักของโครงการ</p></div>${p.role==='OWNER'?'<button id="editProjectInfo">แก้ไขข้อมูลโครงการ</button>':''}</div><div class='contract-grid'>${infoCell('สัญญา',i.contractName)}${infoCell('สัญญาเลขที่',i.contractNo)}${infoCell('เลขของาน LSF',i.lsfNo)}${infoCell('วันที่ลงนามในสัญญา',i.signedDate)}${infoCell('วันเริ่มต้นโครงการตามสัญญา',i.projectStartDate)}${infoCell('ส่งมอบงานให้แล้วเสร็จภายในวันที่',i.deliveryDueDate)}${infoCell('เลขโครงการ',i.projectCode)}${infoCell('มูลค่าสัญญา',money(i.contractValue))}</div></section><section class='card' id='paymentSummary'><div class='row'><div><h2>สรุปงวดเงิน</h2><p class='muted'>คำนวณจากสัดส่วนเงินเทียบกับมูลค่าสัญญา</p></div><strong>รวม ${num(s.totalPercent)}% · เหลือ ${num(s.remainingPercent)}%</strong></div><div class='payment-grid'>${Object.entries(s.groups||{}).map(([no,g])=>`<div class='payment-card'><strong>งวดเงิน ${esc(no)}</strong><span>${num(g.percent)}%</span><small>${money(g.amount)}</small></div>`).join('')||'<div class="empty">ยังไม่มีงวดเงิน</div>'}</div></section><section class='card sheet-card'><div class='row'><div><h2>งวดงาน / TOR / ส่งมอบ</h2><p class='muted'>Read Mode / Edit Mode แบบ spreadsheet</p></div><div class='row'><button id='toggleTorEdit' ${p.role==='VIEWER'||p.completed?'disabled':''}>${torEdit?'Read Mode':'Edit Mode'}</button>${torEdit&&p.role!=='VIEWER'&&!p.completed?'<button id="addMilestone" class="primary">+ เพิ่มงวดงาน</button>':''}</div></div><div class='sheet-wrap'><table class='sheet'><thead><tr><th>งวดงานที่</th><th>งวดเงินที่</th><th>สัดส่วนเงิน (%)</th><th>งวดตามสัญญา</th><th>สิ่งส่งมอบ</th><th>ขอบเขตของงาน</th><th>ข้อในสัญญา</th><th>กำหนดส่งมอบ (ตามสัญญา)</th><th>วัน</th><th>กำหนดส่งมอบ (ตาม TOR)</th><th>กำหนดส่งมอบ (ตามแผน)</th><th>เดือน</th><th>วันที่ส่งมอบ</th><th>เลขที่/วันที่ จดหมาย</th><th>เลขที่/วันที่ หนังสือตอบกลับ(ลูกค้า)</th><th>วันที่เซ็นต์รับมอบ(ลูกค้า)</th><th>สถานะ</th><th></th></tr></thead><tbody>${(p.milestones||[]).map(m=>torRow(m,p)).join('')||'<tr><td colspan="18" class="empty">ยังไม่มีงวดงาน</td></tr>'}</tbody></table></div></section><section class='card' id='torAudit'><h2>ประวัติการแก้ไข TOR / ส่งมอบ</h2>${p.events.filter(e=>['milestone_cell','milestone_details','milestone_add','milestone_delete','project_info'].includes(e.action)).slice(0,50).map(e=>`<div class='timeline'><strong>${esc(e.actor)}</strong><p class='muted'>${esc(new Date(e.at).toLocaleString('th-TH'))}</p><p>${esc(torEvent(e))}</p></div>`).join('')||'<div class="empty">ยังไม่มีประวัติ</div>'}</section>`}
function torView(p){const i=p.projectInfo||{},s=p.paymentSummary||{},labels=p.milestoneLabels||{};return `<section class='card'><div class='row'><div><h2>ข้อมูลโครงการ / สัญญา</h2><p class='muted'>ข้อมูลอ้างอิงหลักของโครงการ</p></div>${p.role==='OWNER'?'<button id="editProjectInfo">แก้ไขข้อมูลโครงการ</button>':''}</div><div class='contract-grid'>${infoCell('สัญญา',i.contractName)}${infoCell('สัญญาเลขที่',i.contractNo)}${infoCell('เลขของาน LSF',i.lsfNo)}${infoCell('วันที่ลงนามในสัญญา',i.signedDate)}${infoCell('วันเริ่มต้นโครงการตามสัญญา',i.projectStartDate)}${infoCell('ส่งมอบงานให้แล้วเสร็จภายในวันที่',i.deliveryDueDate)}${infoCell('เลขโครงการ',i.projectCode)}${infoCell('มูลค่าสัญญา',money(i.contractValue))}</div></section><section id='paymentSummary' class='card'><div class='row'><h2>สรุปงวดเงิน</h2><strong>รวม ${num(s.totalPercent)}% · เหลือ ${num(s.remainingPercent)}%</strong></div><div class='payment-grid'>${Object.entries(s.groups||{}).map(([no,g])=>`<div class='payment-card'><strong>งวดเงิน ${esc(no)}</strong><span>${num(g.percent)}%</span><small>${money(g.amount)}</small></div>`).join('')||'<div class="empty">ยังไม่มีงวดเงิน</div>'}</div></section><section class='card sheet-card'><div class='row'><div><h2>งวดงาน / TOR / ส่งมอบ</h2><p class='muted'>เปลี่ยนชื่อหัวตารางได้โดยข้อมูลเดิมไม่หาย</p></div><div class='row'><button id='toggleTorEdit' ${p.role==='VIEWER'||p.completed?'disabled':''}>${torEdit?'Read Mode':'Edit Mode'}</button>${torEdit&&p.role!=='VIEWER'&&!p.completed?'<button id="addMilestone" class="primary">+ เพิ่มงวดงาน</button><button id="renameHeaders">แก้ชื่อหัวตาราง</button>':''}</div></div><div class='sheet-wrap'><table class='sheet'><thead><tr>${torCols.map(f=>`<th>${esc(labels[f]||f)}</th>`).join('')}<th></th></tr></thead><tbody>${(p.milestones||[]).map(m=>torRow(m,p)).join('')||'<tr><td colspan="18" class="empty">ยังไม่มีงวดงาน</td></tr>'}</tbody></table></div></section><section id='torAudit' class='card'><h2>ประวัติการแก้ไข TOR / ส่งมอบ</h2>${p.events.filter(e=>['milestone_cell','milestone_details','milestone_add','milestone_delete','milestone_header','project_info'].includes(e.action)).slice(0,50).map(e=>`<div class='timeline'><strong>${esc(e.actor)}</strong><small> · ${esc(new Date(e.at).toLocaleString('th-TH'))}</small><p>${esc(torEvent(e))}</p></div>`).join('')||'<div class="empty">ยังไม่มีประวัติ</div>'}</section>`}
const torCols=['workNo','paymentNo','paymentPercent','contractMilestone','deliverables','scope','contractClause','contractDue','days','torDue','planDue','month','deliveredDate','letterRef','customerReplyRef','customerAcceptedDate','status'];
function torRow(m,p){return `<tr>${torCols.map(f=>`<td>${torEdit&&p.role!=='VIEWER'&&!p.completed?torInput(m,f):torRead(m,f)}</td>`).join('')}<td><button data-detail-milestone='${m.id}'>รายละเอียด</button>${torEdit&&p.role!=='VIEWER'&&!p.completed?`<button data-delete-milestone='${m.id}'>ลบ</button>`:''}</td></tr>`}
function torRead(m,f){if(f==='status')return `<span class='badge'>${esc(milestoneStatusName[m[f]]||m[f]||'—')}</span>`;if(f==='paymentPercent')return m[f]?`${num(m[f])}%`:'—';return `<div class='cell-text'>${esc(m[f]||'—')}</div>`}
const cellDrafts=new Map();
const pendingCells=new Set();
function draftKey(project,id,field){return `${project}/${id}/${field}`}
function isoDate(value){const text=String(value||'');const parts=text.split('/');if(parts.length!==3)return text;let [d,m,y]=parts.map(Number);if(y>2400)y-=543;return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function torInput(m,f){const key=draftKey(selected,m.id,f),value=cellDrafts.has(key)?cellDrafts.get(key):m[f]??'';const attrs=`class='cell-input' aria-label='งวด ${esc(m.workNo)} ${esc(f)}' data-mid='${m.id}' data-field='${f}'`;
 if(f==='status')return `<select ${attrs}>${state.milestoneStatuses.map(s=>option(s,milestoneStatusName[s],value)).join('')}</select>`;
 if(f==='paymentPercent')return `<input type='number' min='0' max='100' step='0.0001' ${attrs} value='${esc(value)}'>`;
 if(['torDue','planDue','deliveredDate','customerAcceptedDate'].includes(f))return `<input type='date' ${attrs} value='${esc(isoDate(value))}'>`;
 return `<textarea ${attrs}>${esc(value)}</textarea>`;
}

function projectInfoForm(){const i=pnow().projectInfo||{};modal('ข้อมูลโครงการ / สัญญา',`<label>สัญญา<input name='contractName' value='${esc(i.contractName||'')}'></label><label>สัญญาเลขที่<input name='contractNo' value='${esc(i.contractNo||'')}'></label><label>เลขของาน LSF<input name='lsfNo' value='${esc(i.lsfNo||'')}'></label><div class='split'><label>วันที่ลงนามในสัญญา<input name='signedDate' value='${esc(i.signedDate||'')}'></label><label>วันเริ่มต้นโครงการตามสัญญา<input name='projectStartDate' value='${esc(i.projectStartDate||'')}'></label><label>ส่งมอบงานให้แล้วเสร็จภายในวันที่<input name='deliveryDueDate' value='${esc(i.deliveryDueDate||'')}'></label><label>เลขโครงการ<input name='projectCode' value='${esc(i.projectCode||'')}'></label><label>มูลค่าสัญญา<input name='contractValue' type='number' step='0.01' min='0' value='${esc(i.contractValue??'')}'></label></div>`,d=>saveInPlace('project_info',d))}

function guide(p){return {Contract:'ตรวจหลักฐานสัญญาและขอบเขตงานก่อนจัดซื้อ',Procurement:'ตรวจ PR/PO และความพร้อมของ vendor',Planning:'กำหนด owner, milestone และ dependency ให้ครบ',Delivery:'ส่งมอบงานพร้อมหลักฐาน และติดตาม blocker',Acceptance:'บันทึกผลตรวจรับและหลักฐานการอนุมัติ ก่อนเตรียม invoice',Billing:'ติดตาม invoice และการชำระเงิน พร้อมอัปเดต forecast',Closure:'ตรวจว่างานทั้งหมดเสร็จ บันทึกบทเรียน และส่งมอบเอกสาร'}[p.phase]}
function wire(){wireControls();$$('[data-view]',b=>b.onclick=async()=>{await cellSaves;try{state=await api('state');view=b.dataset.view;if(view==='home')selected=undefined;else if(!selected&&!['admin','inbox','my'].includes(view))selected=state.projects[0]?.id;render()}catch(e){tell(e.message)}});$('#projectSelect').onchange=e=>{selected=e.target.value||undefined;view=selected?'overview':'home';torEdit=false;render()};$$('[data-open-project]',b=>b.onclick=()=>{selected=b.dataset.openProject;view='overview';render()});$('#newProject')?.addEventListener('click',()=>modal('สร้างโครงการ','<label>ชื่อโครงการ<input name="name" required maxlength="200"></label>',d=>act('create_project',d)));$('#addAdminUser')?.addEventListener('click',()=>adminUserForm());$$('[data-admin-user]',b=>b.onclick=()=>adminUserForm(b.dataset.adminUser));$$('[data-admin-member]',b=>b.onchange=async()=>{try{await api('action',{action:'admin_membership',project:b.dataset.project,user:b.dataset.adminMember,role:b.value});await refresh();view='admin';render();tell('อัปเดตสิทธิ์สมาชิกแล้ว')}catch(e){tell(e.message);await refresh();view='admin';render()}});if($('#logout'))$('#logout').onclick=async()=>{await api('logout',{});login()};$$('[data-task]',b=>b.onclick=()=>{selected=b.dataset.project;taskForm(b.dataset.task)});if($('#addTask'))$('#addTask').onclick=()=>taskForm();if($('#settings'))$('#settings').onclick=settings;if($('#handover'))$('#handover').onclick=handoverForm;if($('#crisisHandover'))$('#crisisHandover').onclick=crisisHandoverForm;if($('#acceptCrisis'))$('#acceptCrisis').onclick=()=>act('crisis_accept',{});if($('#addMember'))$('#addMember').onclick=()=>member();$$('[data-member]',b=>b.onclick=()=>member(b.dataset.member));$$('[data-notice]',b=>b.onclick=()=>act('read_notice',{id:Number(b.dataset.notice)}));if($('#editProjectInfo'))$('#editProjectInfo').onclick=projectInfoForm;if($('#toggleTorEdit'))$('#toggleTorEdit').onclick=async()=>{await cellSaves;torEdit=!torEdit;render()};if($('#addMilestone'))$('#addMilestone').onclick=()=>act('milestone_add',{});$$('[data-delete-milestone]',b=>b.onclick=()=>{if(confirm('ลบงวดงานนี้?'))act('milestone_delete',{id:b.dataset.deleteMilestone})});$$('.cell-input',el=>{el.onchange=()=>commitTorCell(el);el.onblur=()=>commitTorCell(el);el.onpaste=e=>pasteTorCells(e,el);el.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();const inputs=[...document.querySelectorAll('.cell-input')];inputs[inputs.indexOf(el)+1]?.focus()}}});}
function adminUserForm(user=''){const current=(state.users||[]).find(x=>x.user===user),disabled=!!current?.disabled;modal(user?'จัดการบัญชี '+user:'สร้างบัญชีผู้ใช้',`<label>ชื่อผู้ใช้<input name="user" value="${esc(user)}" ${user?'readonly':''} required maxlength="100"></label><label>${user?'รหัสผ่านใหม่ (เว้นว่างเพื่อเปลี่ยนสถานะเท่านั้น)':'รหัสผ่าน'}<input name="password" type="password" ${user?'':'required'} maxlength="1024" autocomplete="new-password"></label><label class="check"><input type="checkbox" name="disabled" ${disabled?'checked':''}> ปิดใช้งานบัญชี</label><p class="muted">รหัสผ่านถูกแฮชก่อนจัดเก็บ บัญชีที่ถูกปิดจะถูกออกจากระบบทุกอุปกรณ์</p>`,async d=>{await api('admin-user',{...d,disabled:d.disabled==='on'});await refresh();view='admin';render()})}
let cellSaves=Promise.resolve();
function commitTorCell(el){
 const row=pnow()?.milestones.find(m=>m.id===el.dataset.mid),field=el.dataset.field;
 const persisted=el.type==='date'?isoDate(row?.[field]):String(row?.[field]??'');
 const key=draftKey(selected,el.dataset.mid,field);
 if(el.value!==persisted&&cellDrafts.get(key)!==el.value&&!pendingCells.has(key))return saveTorCell(el);
 return cellSaves;
}
function saveTorCell(el){
    const project=selected, id=el.dataset.mid, field=el.dataset.field, value=el.value;
    const key=draftKey(project,id,field);if(pendingCells.has(key))return cellSaves;pendingCells.add(key);cellDrafts.set(key,value);tell('กำลังบันทึก…');
    cellSaves=cellSaves.then(async()=>{
        try{
            await api('action',{action:'milestone_cell',project,id,field,value});
            state=await api('state');
            if(cellDrafts.get(key)===value)cellDrafts.delete(key);
            if(selected===project && view==='tor'){
                // Update derived panels without replacing another cell being edited.
                const fragment=document.createElement('div');
                fragment.innerHTML=torView(pnow());
                for(const selector of ['#paymentSummary','#torAudit']){
                    const target=$(selector);
                    if(target)target.innerHTML=fragment.querySelector(selector).innerHTML;
                }
                const row=pnow().milestones.find(m=>m.id===id);
                if(el.isConnected && el.value===value && row)el.value=el.type==='date'?isoDate(row[field]):row[field];
            }
            tell('บันทึกแล้ว');
        }catch(e){
            tell(e.message+' · เก็บค่าที่พิมพ์ไว้แล้ว กรุณาแก้ไขแล้วบันทึกอีกครั้ง');
        }finally{pendingCells.delete(key)}
    });
    return cellSaves;
}

function $$(s,fn){document.querySelectorAll(s).forEach(fn)}
async function act(action,d){await api('action',{...d,action,project:selected});await refresh();tell('บันทึกแล้ว')}
async function saveInPlace(action,d){const project=selected,page=view;await api('action',{...d,action,project});state=await api('state');selected=project;view=page;render();tell('บันทึกแล้ว')}
function modal(title,html,save){const el=$('#dialog');el.innerHTML=`<form id="modalForm"><h2>${title}</h2>${html}<p id="modalError" role="alert" class="bad-text"></p><div class="actions"><button type="button" id="cancel">ปิด</button>${save?'<button class="primary" id="save">บันทึก</button>':''}</div></form>`;if(!el.open)el.showModal();$('#cancel').onclick=()=>el.close();$('#modalForm').onsubmit=async e=>{e.preventDefault();if(!save)return;$('#modalError').textContent='';$('#save').disabled=true;try{await save(Object.fromEntries(new FormData(e.target)));el.close()}catch(err){$('#modalError').textContent=err.message;if($('#save'))$('#save').disabled=false}};}
function settings(){const p=pnow();modal('ตั้งค่าโครงการ',`<label>ชื่อโครงการ<input name="name" value="${esc(p.name)}" required></label><label>Phase<select name="phase">${state.phases.map(x=>option(x,state.phaseLabels?.[x]||x,p.phase)).join('')}</select></label><label>Milestone ถัดไป<input name="milestone" value="${esc(p.milestone)}"></label><label>กำหนดส่ง<input type="date" name="due" value="${p.due}"></label><label class="check"><input type="checkbox" name="completed" ${p.completed?'checked':''}>ปิดโครงการ (ต้องผ่านรายการตรวจรับ การเงิน และปิดงาน)</label>`,d=>act('project',{...d,completed:d.completed==='on'}))}
function member(user){const p=pnow(),old=p.members.find(m=>m.user===user);modal(user?'จัดการสมาชิก':'เพิ่มสมาชิก',`<label>ชื่อบัญชีผู้ใช้<input name="user" value="${esc(user||'')}" ${user?'readonly':''} required></label><p class="muted">ใช้ชื่อบัญชีที่ผู้ดูแลสร้างไว้แล้ว</p><label>สิทธิ์<select name="role">${(p.role==='OWNER'?['VIEWER','EDITOR','OWNER',...(old?['REMOVE']:[])]:['VIEWER','EDITOR']).map(r=>option(r,r,old?.role)).join('')}</select></label>`,d=>act('member',d))}
function taskForm(id){const p=pnow(),t=p.tasks.find(t=>t.id===id)||{status:'TODO',owner:state.user,dependencies:[],comments:[]};const writable=p.role!=='VIEWER'&&!p.completed;const fields=`<fieldset ${writable?'':'disabled'}><label>ชื่องาน<input name="title" value="${esc(t.title||'')}" required maxlength="200"></label><div class="split"><label>ผู้รับผิดชอบ<select name="owner">${p.members.map(m=>option(m.user,m.user,t.owner)).join('')}</select></label><label>ผู้รับผิดชอบสำรอง<select name="backupOwner">${option('','ยังไม่ระบุ',t.backupOwner)}${p.members.map(m=>option(m.user,m.user,t.backupOwner)).join('')}</select></label><label>กำหนดส่ง<input type="date" name="due" value="${t.due||''}"></label><label>สถานะ<select name="status">${state.statuses.map(s=>option(s,statusName[s],t.status)).join('')}</select></label><label>ความสำคัญ<select name="priority">${['NORMAL','HIGH','LOW'].map(s=>option(s,s,t.priority)).join('')}</select></label></div><label>รอใคร / สิ่งที่ติดขัด<input name="waiting" value="${esc(t.waiting||'')}"></label><label>ขั้นตอนถัดไป<textarea name="next">${esc(t.next||'')}</textarea></label><label>ทำอะไรแล้ว<textarea name="doneNote">${esc(t.doneNote||'')}</textarea></label><label>เหลืออะไร / ผู้รับช่วงต้องรู้<textarea name="remainingNote">${esc(t.remainingNote||'')}</textarea></label><label>หลักฐาน / ลิงก์เอกสาร<textarea name="evidence">${esc(t.evidence||'')}</textarea></label><label>งานที่ต้องเสร็จก่อน (เลือกได้หลายงาน)<select name="dependencies" multiple>${p.tasks.filter(x=>x.id!==id).map(x=>`<option value="${x.id}" ${t.dependencies.includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label></fieldset>`;modal(id?'รายละเอียดงาน':'เพิ่มงาน',fields+(id?`<h3>ความคิดเห็น</h3>${t.comments.map(c=>`<div class="timeline"><strong>${esc(c.author)}</strong><p>${esc(c.text)}</p></div>`).join('')}${writable?'<button type="button" id="commentButton">แสดงความคิดเห็น / @mention</button>':''}`:''),writable?d=>act('task',{...d,id,dependencies:[...$('#dialog select[multiple]').selectedOptions].map(o=>o.value)}):null);if($('#commentButton'))$('#commentButton').onclick=()=>modal('แสดงความคิดเห็น','<label>ข้อความ (ใช้ @ชื่อผู้ใช้ เพื่อแจ้งเตือน)<textarea name="text" required maxlength="4000"></textarea></label>',d=>act('comment',{...d,id}));}

const kindLabels={CONTRACT_REVIEW:'ตรวจสัญญา / TOR',PROJECT_OPENING:'เปิดโครงการ',BANK_GUARANTEE:'หลักประกันสัญญา',STAMP_DUTY:'อากรแสตมป์',KICKOFF:'ประชุมเริ่มงาน',COST_SHEET:'Cost Sheet',APPROVED_BUDGET:'งบประมาณอนุมัติ',ADVANCE_CASH:'เงินทดรอง',FORECAST:'ประมาณการ',PR:'ใบขอซื้อ (PR)',PO:'ใบสั่งซื้อ (PO)',VENDOR_CONTRACT:'สัญญา Vendor',VENDOR_PROGRESS:'ความก้าวหน้า Vendor',ACCOUNTING_REPORT:'รายงานส่งบัญชี',NOT_STARTED:'ยังไม่เริ่ม',READY:'พร้อมดำเนินงาน',AT_RISK:'มีความเสี่ยง',RISK:'ความเสี่ยง',ISSUE:'ประเด็นปัญหา',BLOCKER:'ตัวติดขัด',INVOICE:'ใบแจ้งหนี้',RC:'RC / เอกสารรับเงิน',CUSTOMER_PAYMENT:'รับเงินลูกค้า',VENDOR_PAYMENT:'จ่ายเงิน Vendor',STANDARD:'ปกติ',BACK_TO_BACK:'Back-to-back',LOW:'ต่ำ',MEDIUM:'ปานกลาง',HIGH:'สูง',CRITICAL:'วิกฤต',DOCUMENT:'เอกสาร',DECISION:'การตัดสินใจ',FINAL_ACCEPTANCE:'ตรวจรับสุดท้าย',ASSET:'ทรัพย์สิน',HANDOVER:'ส่งมอบผู้ดูแลต่อ',LESSONS:'บทเรียน',WARRANTY:'รับประกัน',GUARANTEE_RELEASE:'คืนหลักประกัน'};
function phaseName(phase){return state.phaseLabels?.[phase]||phase}
function phaseStrip(p){return `<div class="phases">${state.phases.map(phase=>`<button data-phase="${phase}" class="phase ${phase===p.phase?'current':''}">${esc(phaseName(phase))}</button>`).join('')}</div>`}
function currentMilestone(p){const m=p.deliverySummary?.current;return m?`งวดที่ ${m.workNo} · ${(m.deliverables||'').split('\n')[0]}`:'ไม่มีงวดงานที่ค้างส่งมอบ'}
const lifecycleSelection=new Map();
const phaseViews={Contract:'opening',Procurement:'procurement',Planning:'planning',Delivery:'tor',Acceptance:'acceptance',Billing:'finance',Closure:'closure'};
function checklistCounts(p,phase){const items=p.lifecycleChecks?.[phase]||[];return {total:items.length,done:items.filter(x=>x.status==='DONE').length}}
function selectedLifecyclePhase(p){return lifecycleSelection.get(p.id)||p.phase||state.phases[0]}
function selectLifecyclePhase(phase){if(!state.phases.includes(phase)||!pnow())return;lifecycleSelection.set(selected,phase);view='lifecycle';render();$(`[data-phase="${phase}"]`)?.focus()}
function checkSection(p,phase){
 const items=p.lifecycleChecks?.[phase]||[],counts=checklistCounts(p,phase),writable=p.role!=='VIEWER'&&!p.completed;
 return `<section class="card checklist-section" id="phase-checklist" aria-label="Checklist ${esc(phaseName(phase))}"><div class="row"><div><span class="eyebrow">CHECKLIST</span><h2>${esc(phaseName(phase))}</h2></div><span class="checklist-count">เสร็จ ${counts.done} / ${counts.total} ข้อ</span></div><div class="checklist-grid">${items.map(item=>`<button type="button" class="checklist-box ${item.status==='DONE'?'is-done':''}" data-check="${esc(item.id)}" aria-label="${writable?'อัปเดต':'ดู'} ${esc(item.title)} · ${esc(statusName[item.status]||'ยังไม่เริ่ม')}"><span class="checklist-square" aria-hidden="true">${item.status==='DONE'?'✓':''}</span><span class="checklist-body"><span class="checklist-title">${esc(item.title)}</span><span class="checklist-meta"><span class="checklist-status ${item.status==='BLOCKED'?'is-blocked':''}">${esc(statusName[item.status]||'ยังไม่เริ่ม')}</span><span>${item.required?'จำเป็น':'แนะนำ'}</span></span><span class="checklist-meta">${esc(item.owner||'ยังไม่มอบหมาย')} · ${esc(item.due||'ยังไม่กำหนดวัน')}</span><span class="checklist-evidence">${item.evidence?'หลักฐาน: '+esc(item.evidence):'ยังไม่บันทึกหลักฐาน'}</span>${item.notes?`<span class="checklist-note">${esc(item.notes)}</span>`:''}<span class="checklist-action">${writable?'อัปเดตรายการ':'ดูรายละเอียด'}</span></span></button>`).join('')||'<p class="empty">ยังไม่มี Checklist ในขั้นตอนนี้</p>'}</div></section>`;
}
function lifecycleView(p){
 const active=selectedLifecyclePhase(p),total=state.phases.reduce((sum,phase)=>sum+checklistCounts(p,phase).total,0),done=state.phases.reduce((sum,phase)=>sum+checklistCounts(p,phase).done,0);
 return `<section class="lifecycle-board"><div class="row lifecycle-heading"><div><span class="eyebrow">PROJECT WORKFLOW</span><h2>ขั้นตอนโครงการ</h2><p class="muted">ขั้นปัจจุบัน: <strong>${esc(phaseName(p.phase))}</strong> · Checklist เสร็จ ${done} / ${total} ข้อ</p></div>${p.role==='OWNER'?'<button id="settings">ตั้งค่าขั้นตอน</button>':''}</div><div class="stage-grid" aria-label="เลือกขั้นตอนเพื่อดู Checklist">${state.phases.map((phase,index)=>{const c=checklistCounts(p,phase);return `<button type="button" class="stage-box ${phase===active?'is-selected':''}" data-phase="${phase}" aria-pressed="${phase===active}" aria-controls="phase-checklist"><span class="stage-top"><span class="stage-number">${String(index+1).padStart(2,'0')}</span>${phase===p.phase?'<span class="stage-current">ขั้นปัจจุบัน</span>':''}</span><span class="stage-title">${esc(phaseName(phase))}</span><span class="stage-summary">Checklist ${c.done} / ${c.total} ข้อ</span><progress value="${c.done}" max="${c.total||1}" aria-label="Checklist ${esc(phaseName(phase))} เสร็จ ${c.done} จาก ${c.total} ข้อ"></progress></button>`}).join('')}</div></section><div class="row phase-detail-heading"><h2>${esc(phaseName(active))}</h2><button data-view="${phaseViews[active]}">เปิด${esc(phaseName(active))}</button></div>${checkSection(p,active)}`;
}
function healthLabel(s){return {ON_TRACK:'ตามแผน','ON TRACK':'ตามแผน',AT_RISK:'มีความเสี่ยง','AT RISK':'มีความเสี่ยง',OVERDUE:'ล่าช้า',BLOCKED:'ติดปัญหา',COMPLETED:'เสร็จแล้ว'}[s]||s}
function healthBadge(s){const label=healthLabel(s);return `<span class="badge ${['BLOCKED','OVERDUE'].includes(s)?'bad':s==='AT_RISK'||s==='AT RISK'?'warn':' '}">${esc(label)}</span>`}
function healthLink(p){return healthBadge(p.health?.status).replace('<span ',`<button type="button" data-health-project="${esc(p.id)}" title="${esc(p.health?.reason||'เปิดงวดงาน')}" aria-label="${esc(healthLabel(p.health?.status))} · เปิดรายการที่เกี่ยวข้อง" `).replace('</span>','</button>')}
async function openHealthTarget(project){
 await cellSaves;state=await api('state');selected=project;const p=pnow();if(!p)return;
 const target=p.health?.target||{view:['ON TRACK','ON_TRACK'].includes(p.health?.status)?'tor':p.controlSummary?.alerts?.[0]?.module||'tasks'};
 if(target.phase)lifecycleSelection.set(project,target.phase);view=target.view;render();
 if(target.type==='task')taskForm(target.id);else if(target.type==='milestone')milestoneDetail(target.id);else if(target.type==='checklist')checklistForm(target.id);else if(target.type==='control')controlForm(target.view,target.id,target.kind?{kind:target.kind}:{});
}
function homeDashboard(){const ps=state.projects||[],crisisCount=ps.filter(p=>p.crisis?.active).length,counts={ON_TRACK:0,AT_RISK:0,OVERDUE:0,BLOCKED:0,COMPLETED:0};ps.forEach(p=>counts[(p.health?.status||'ON TRACK').replaceAll(' ','_')]++);return `<section class="card"><div class="row"><div><span class="eyebrow">HOME / MY PROJECTS</span><h2>โครงการของฉัน</h2><p class="muted">แสดงเฉพาะโครงการที่คุณมี membership อยู่</p></div></div><div class="metrics"><div class="metric"><span>โครงการทั้งหมด</span><strong>${ps.length}</strong></div><div class="metric"><span>ตามแผน</span><strong>${counts.ON_TRACK||0}</strong></div><div class="metric"><span>มีความเสี่ยง</span><strong>${counts.AT_RISK||0}</strong></div><div class="metric"><span>ติดปัญหา</span><strong>${counts.BLOCKED||0}</strong></div><div class="metric"><span>ล่าช้า</span><strong>${counts.OVERDUE||0}</strong></div><div class="metric"><span>Crisis Handover</span><strong>${crisisCount}</strong></div></div></section><div class="project-grid">${ps.map(p=>{const cur=p.deliverySummary?.current,next=p.deliverySummary?.next;return `<article class="card project-card"><div class="row"><div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.projectInfo?.projectCode||'ยังไม่มี Project Code')}</p></div>${p.crisis?.active?'<span class="badge bad">CRISIS</span>':''}${healthLink(p)}</div><p><strong>${esc(p.role)}</strong> · ${esc(phaseName(p.phase))}</p><div class="project-current"><span>Current</span><strong>${cur?'งวดงานที่ '+esc(cur.workNo):p.completed?'เสร็จแล้ว':'ยังไม่มีงวดงาน'}</strong><span>Next</span><strong>${next?'งวดงานที่ '+esc(next.workNo):'—'}</strong></div><button class="primary" data-open-project="${p.id}">เปิดโครงการ</button></article>`}).join('')||'<section class="card empty"><h2>ยังไม่มีโครงการ</h2><p>สร้างโครงการแรกจากปุ่มด้านบน</p></section>'}</div>`}
function planningView(p){const rows=p.milestones||[],tasks=p.tasks||[],writable=p.role!=='VIEWER'&&!p.completed,done=tasks.filter(t=>t.status==='DONE').length;return `<section class="card"><div class="row"><div><span class="eyebrow">PROJECT PLAN</span><h2>แผนงานและกำหนดส่ง</h2><p class="muted">ดู baseline ตามสัญญา เทียบกำหนดในแผน พร้อม dependency และ owner</p></div><div class="row">${writable?'<button id="addPlanningTask">+ เพิ่มงาน</button><button id="addPlanningMilestone" class="primary">+ เพิ่มงวดงาน</button>':''}</div></div><div class="metrics"><div class="metric"><span>งวดที่เสร็จ / ทั้งหมด</span><strong>${p.deliverySummary?.done||0} / ${rows.length}</strong></div><div class="metric"><span>งานย่อยที่เสร็จ</span><strong>${done} / ${tasks.length}</strong></div><div class="metric"><span>งวดปัจจุบัน</span><strong>${p.deliverySummary?.current?'งวด '+esc(p.deliverySummary.current.workNo):'—'}</strong></div><div class="metric"><span>กำหนดโครงการ</span><strong>${esc(p.projectInfo?.deliveryDueDate||p.due||'ยังไม่กำหนด')}</strong></div></div></section><section class="card"><h2>Timeline งวดส่งมอบ</h2><div class="table-wrap"><table><thead><tr><th>งวด</th><th>สถานะ</th><th>สิ่งส่งมอบ</th><th>สัญญา</th><th>TOR</th><th>แผน</th><th>ผู้รับผิดชอบ</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.workNo)}</td><td>${esc(milestoneStatusName[m.status]||'ยังไม่ระบุ')}</td><td>${esc((m.deliverables||'').split('\n')[0]||'—')}</td><td>${esc(m.contractDue||'—')}</td><td>${esc(m.torDue||'—')}</td><td>${esc(m.planDue||'—')}</td><td>${esc(m.owner||'ยังไม่มอบหมาย')}</td><td><button data-detail-milestone="${m.id}">เปิดแผน</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">ยังไม่มีงวดส่งมอบ</td></tr>'}</tbody></table></div></section><section class="card"><div class="row"><h2>งานย่อยและ dependency</h2><button data-view="tasks">เปิดรายการงานทั้งหมด</button></div>${tasks.map(t=>`<div class="task"><div><h3>${esc(t.title)}</h3><p>${badge(t.status)} · ${esc(t.owner)} · กำหนด ${esc(t.due||'ไม่ระบุ')} · ต้องรอ ${t.dependencies?.length||0} งาน</p>${t.waiting?`<p class="muted">รอ/ติดขัด: ${esc(t.waiting)}</p>`:''}</div><button data-task="${t.id}" data-project="${p.id}">เปิดงาน</button></div>`).join('')||'<p class="empty">ยังไม่มีงานย่อยในแผน</p>'}</section>${p.lifecycleChecks?.Planning?checkSection(p,'Planning'):''}`}
function acceptanceView(p){const rows=p.controls?.acceptance||[],d=p.deliverySummary||{},writable=p.role!=='VIEWER'&&!p.completed;return `<section class="card"><div class="row"><div><span class="eyebrow">CUSTOMER ACCEPTANCE</span><h2>ตรวจรับงานและหลักฐาน</h2><p class="muted">แยกสถานะส่งมอบออกจากการตรวจรับของลูกค้า และเก็บเลขหนังสือตอบกลับ</p></div>${writable?'<button data-add-control="acceptance" class="primary">+ เพิ่มรายการตรวจรับ</button>':''}</div><div class="metrics"><div class="metric"><span>ส่งมอบแล้ว</span><strong>${d.done||0} / ${d.total||0} งวด</strong></div><div class="metric"><span>ลูกค้าตรวจรับแล้ว</span><strong>${d.accepted||0} / ${d.total||0} งวด</strong></div><div class="metric"><span>รายการตรวจรับค้าง</span><strong>${rows.filter(r=>r.status!=='DONE').length}</strong></div></div></section><section class="card"><h2>รายการตรวจรับและหนังสือตอบกลับ</h2>${rows.map(r=>`<div class="task"><div><h3>${esc(r.title)}</h3><p>${esc(kindLabels[r.kind]||'ตรวจรับ')} · ${esc(statusName[r.status]||'ยังไม่เริ่ม')} · ${esc(r.owner||'ยังไม่มอบหมาย')} · กำหนด ${esc(r.due||'—')}</p><p>งวดงาน: ${esc((p.milestones||[]).find(m=>m.id===r.milestoneId)?.workNo||'—')} · หนังสือตอบกลับ ${esc(r.customerReplyRef||'ยังไม่มี')} · เซ็นรับ ${esc(r.customerAcceptedDate||'ยังไม่มี')}</p>${r.evidence?`<p class="muted">หลักฐาน: ${esc(r.evidence)}</p>`:''}</div>${writable?`<button data-edit-control="${r.id}" data-module="acceptance">แก้ไข</button>`:''}</div>`).join('')||'<p class="empty">ยังไม่มีรายการตรวจรับ ให้เพิ่มการตรวจเอกสาร/ผลทดสอบและหลักฐานการรับมอบ</p>'}</section>${checkSection(p,'Acceptance')}`}
function adminView(){const users=state.users||[],projects=state.adminProjects||[],events=state.adminEvents||[];return `<section class="card"><div class="row"><div><span class="eyebrow">SYSTEM ADMIN</span><h2>บัญชีผู้ใช้</h2><p class="muted">สร้างบัญชี ตั้งรหัสใหม่ และปิด/เปิดใช้งานบัญชีได้ รหัสถูกแฮชและ session จะถูกเพิกถอนเมื่อปิดบัญชี</p></div><button id="addAdminUser" class="primary">+ สร้างบัญชี</button></div>${users.map(r=>`<div class="task"><div><h3>${esc(r.user)}</h3><small>สร้างโดย ${esc(r.createdBy||'ระบบ')} · ${esc(r.createdAt||'บัญชีเดิม')}</small></div><div class="row">${r.disabled?badge('BLOCKED'):badge('DONE')}<button data-admin-user="${esc(r.user)}">จัดการ / Reset</button></div></div>`).join('')||'<p class="empty">ยังไม่มีบัญชีผู้ใช้</p>'}</section><section class="card"><h2>สิทธิ์สมาชิกทุกโครงการ</h2><p class="muted">OWNER ดูแลโครงการทั้งหมด; เปลี่ยน role หรือนำผู้ใช้ออกจากโครงการได้จากรายการนี้</p>${projects.map(p=>`<section class="admin-project"><div class="row"><div><h3>${esc(p.name)}</h3><small>${esc(p.projectCode||'ไม่มี Project Code')} · ${esc(phaseName(p.phase))}</small></div></div>${users.map(u=>{const member=p.members.find(m=>m.user===u.user),current=member?.role||'REMOVE';return `<div class="task"><div><strong>${esc(u.user)}</strong> ${u.disabled?badge('BLOCKED'):''}</div><label class="inline-label">สิทธิ์<select data-admin-member="${esc(u.user)}" data-project="${esc(p.id)}">${option('REMOVE','ไม่มีสิทธิ์ / นำออก',current)}${option('VIEWER','VIEWER · อ่านอย่างเดียว',current)}${option('EDITOR','EDITOR · แก้ไขข้อมูล',current)}${option('OWNER','OWNER · จัดการโครงการ',current)}</select></label></div>`}).join('')||'<p class="empty">ยังไม่มีบัญชีสำหรับกำหนดสมาชิก</p>'}</section>`).join('')||'<p class="empty">ยังไม่มีโครงการ</p>'}</section><section class="card"><h2>System Admin Audit Log</h2>${events.map(e=>`<div class="timeline"><strong>${esc(e.actor)}</strong><small> · ${esc(new Date(e.at).toLocaleString('th-TH'))}</small><p>${esc(e.action==='admin_user'?`บัญชี ${JSON.parse(e.detail).user}: ${JSON.parse(e.detail).action}`:e.action==='admin_membership'?`สมาชิก ${JSON.parse(e.detail).user||''} · ${JSON.parse(e.detail).before||'ใหม่'} → ${JSON.parse(e.detail).after||''}`:eventSummary(e))}</p></div>`).join('')||'<p class="empty">ยังไม่มีรายการ audit</p>'}</section>`}
function legacyHomeView(p){
 const d=p.deliverySummary||{total:0,done:0,accepted:0,percent:0,overdue:[],blocked:[]},c=p.controlSummary||{alerts:[],openRisks:0};
 const pending=p.tasks.filter(t=>t.status!=='DONE');
 const current=d.current;
 const owners=(p.members||[]).filter(m=>m.role==='OWNER').map(m=>m.user).join(', ');
 return `<section class="card"><div class="row"><div><h2>สถานะโครงการ · ${esc(phaseName(p.phase))}</h2>${badge(p.health.status)} <span class="muted">${esc(p.health.reason)}</span><p>เจ้าของโครงการ: ${esc(owners||'ยังไม่ระบุ')}</p></div>${p.role==='OWNER'?'<button id="settings">ตั้งค่าโครงการ</button>':''}</div>${phaseStrip(p)}</section>
 <div class="metrics"><div class="metric"><span>งวดงานเสร็จ / ส่งมอบแล้ว</span><strong>${d.done} / ${d.total} งวด · ${num(d.percent)}%</strong><progress value="${d.done}" max="${d.total||1}"></progress><small>นับจำนวนงวด ไม่ใช่สัดส่วนเงินหรือยอดรับชำระ</small></div><div class="metric"><span>ลูกค้าตรวจรับแล้ว</span><strong>${d.accepted} / ${d.total} งวด</strong><small>ต้องยืนยันสถานะตรวจรับแยกจากการส่งมอบ</small></div><div class="metric"><span>งวดเกินกำหนด / ติดขัด</span><strong>${d.overdue.length} / ${d.blocked.length}</strong><small>ความเสี่ยงที่ยังไม่ปิด ${c.openRisks} รายการ</small></div></div>
 <section class="card focus-card"><span class="eyebrow">งานปัจจุบัน</span><h2>${esc(currentMilestone(p))}</h2>${current?`<p>${esc(milestoneStatusName[current.status]||'ยังไม่ระบุสถานะ')} · กำหนดตามแผน <strong>${esc(current.planDue||'ยังไม่ระบุ')}</strong> · ตาม TOR ${esc(current.torDue||'ยังไม่ระบุ')}</p><p>ผู้รับผิดชอบ: ${esc(current.owner||'ยังไม่มอบหมาย')}</p><p>ขั้นต่อไป: ${current.next?esc(current.next):current.status==='READY'?'จัดส่งงานและบันทึกวันที่/หนังสือส่งมอบ':'ดำเนินการตามสิ่งส่งมอบ ตรวจหลักฐาน และเตรียมส่งมอบงวดนี้'}</p>`:''}<button data-view="tor" class="primary">เปิด TOR / อัปเดตงวดงาน</button></section>
 <section class="card"><h2>เส้นทางส่งมอบ</h2>${(p.milestones||[]).map(m=>`<div class="task"><div><strong>งวดที่ ${esc(m.workNo)} · ${esc((m.deliverables||'').split('\n')[0])}</strong><p>${esc(milestoneStatusName[m.status]||'ยังไม่ระบุ')} · ตามแผน ${esc(m.planDue||'—')} · ส่งมอบ ${esc(m.deliveredDate||'—')}</p></div><button data-view="tor">ดูรายละเอียด</button></div>`).join('')||'<p>ยังไม่มีงวดงาน</p>'}</section>
 <div class="grid"><section class="card"><h2>สิ่งที่ต้องตรวจ / ติดตาม</h2>${c.alerts.map(a=>`<div class="task"><p>${esc(a.title)}</p><button data-view="${esc(a.module)}">เปิดรายการ</button></div>`).join('')||'<p>ไม่มีข้อแจ้งเตือนจากข้อมูลที่บันทึกไว้</p>'}<p class="muted">รายการที่ยังไม่มีข้อมูลไม่ถือว่ายืนยันเสร็จแล้ว</p></section><section class="card"><h2>การเงิน</h2>${c.financeRecorded?`<p>รับเงินลูกค้าที่บันทึกแล้ว: ${money(c.received)}</p><p>จ่าย Vendor ที่บันทึกแล้ว: ${money(c.paid)}</p><p>รับหักจ่าย: ${money(c.net)}</p>`:'<p>ยังไม่มีข้อมูลรับ–จ่ายเงินจริง</p>'}<button data-view="finance">เปิดการเงิน</button><p>สัดส่วนงวดเงิน ${num(p.paymentSummary?.totalPercent)}% · ไม่ใช่ยอดรับชำระแล้ว</p></section></div>
 ${checkSection(p,p.phase)}
 <div class="grid"><section class="card"><div class="row"><h2>งานย่อยคงค้าง · ${pending.length}</h2>${p.role!=='VIEWER'&&!p.completed?'<button id="addTask">+ เพิ่มงาน</button>':''}</div>${tasksHtml(pending.slice(0,5),p)}</section><section class="card"><div class="row"><h2>บันทึกส่งต่องาน</h2>${p.role!=='VIEWER'&&!p.completed?'<button id="handover">อัปเดต</button>':''}</div><pre>${esc(p.handover||'ยังไม่มีบันทึกส่งต่องาน')}</pre></section></div>
 <section class="card"><h2>ความเคลื่อนไหวล่าสุด</h2>${p.events.slice(0,15).map(e=>`<div class="timeline"><strong>${esc(e.actor)}</strong> · ${esc(new Date(e.at).toLocaleString('th-TH'))}<p>${esc(eventSummary(e))}</p></div>`).join('')}</section>`;
}
function controlView(p,module){const meta=state.controlModules[module],rows=(p.controls?.[module]||[]).filter(r=>module!=='procurement'||r.kind!=='VENDOR_CONTRACT');return `<section class="card"><div class="row"><div><h2>${esc(module==='opening'?'สัญญาลูกค้า / เริ่มงาน':meta.label)}</h2><p>บันทึกผู้รับผิดชอบ กำหนดเวลา และหลักฐานของแต่ละรายการ</p></div>${p.role!=='VIEWER'&&!p.completed?`<button data-add-control="${module}" class="primary">+ เพิ่มรายการ</button>`:''}</div>${module==='opening'?`<p>เลขสัญญา ${esc(p.projectInfo?.contractNo||'ยังไม่ระบุ')} · เลขของาน LSF ${esc(p.projectInfo?.lsfNo||'ยังไม่ระบุ')} · ลงนาม ${esc(p.projectInfo?.signedDate||'—')} · เริ่ม ${esc(p.projectInfo?.projectStartDate||'—')}</p>${p.role==='OWNER'?'<button id="editProjectInfo">แก้ไขข้อมูลโครงการ / สัญญา</button>':''}`:''}${module==='closure'?`<h3>${p.completed?'ปิดโครงการแล้ว':'ตรวจความพร้อมก่อนปิดโครงการ'}</h3>${(p.closureBlockers||[]).map(x=>`<p>• ${esc(x)}</p>`).join('')||'<p>รายการจำเป็นครบแล้ว</p>'}${p.role==='OWNER'?'<button id="settings">ตั้งค่า Phase / ปิด–เปิดโครงการ</button>':''}`:''}</section>${['opening','procurement'].includes(module)?vendorContractSection(p):''}${rows.map(r=>`<section class="card"><div class="row"><h3>${esc(r.title)}</h3>${p.role!=='VIEWER'&&!p.completed?`<button data-edit-control="${r.id}" data-module="${module}">แก้ไข</button>`:''}</div><p>${esc(kindLabels[r.kind]||kindLabels[r.severity]||'')} · ${esc(statusName[r.status])} · ${esc(r.owner||'ยังไม่มอบหมาย')} · กำหนด ${esc(r.due||'—')}</p><div class="contract-grid">${meta.fields.filter(([key])=>!['title','owner','due','status'].includes(key)&&r[key]!==''&&r[key]!=null).map(([key,label,type])=>infoCell(label,type==='money'?money(r[key]):kindLabels[r[key]]||r[key])).join('')}</div>${commentsHtml(r.comments)}${p.role!=='VIEWER'&&!p.completed?`<button data-record-comment="${r.id}" data-module="${module}">เพิ่มความคิดเห็น / @mention</button>`:''}</section>`).join('')||'<section class="card empty">ยังไม่มีรายการในหมวดนี้ · ไม่ถือว่ายืนยันเสร็จแล้ว</section>'}${checkSection(p,meta.phase)}`}
function controlForm(module,id,preset={}){if(module==='procurement'&&pnow().controls?.procurement?.find(r=>r.id===id)?.kind==='VENDOR_CONTRACT')return vendorContractForm(id);const p=pnow(),meta=state.controlModules[module],row=(p.controls?.[module]||[]).find(r=>r.id===id)||{status:'TODO',...preset};
 const related=[...p.tasks.map(t=>({id:t.id,title:t.title})),...p.milestones.map(m=>({id:m.id,title:'งวด '+m.workNo})),...Object.values(p.controls||{}).flat()];
 const html=meta.fields.map(([key,label,type,choices])=>{const value=row[key]??'';let input;
 if(type==='textarea')input=`<textarea name="${key}">${esc(value)}</textarea>`;
 else if(['select','status','member','milestone','related','customerPayment'].includes(type)){
  let options=type==='select'?choices.map(v=>[v,kindLabels[v]||v]):type==='status'?state.statuses.map(v=>[v,statusName[v]]):type==='member'?p.members.map(m=>[m.user,m.user]):type==='milestone'?p.milestones.map(m=>[m.id,'งวด '+m.workNo]):type==='customerPayment'?(p.controls?.finance||[]).filter(r=>r.kind==='CUSTOMER_PAYMENT'&&r.status==='DONE').map(r=>[r.id,r.title]):related.map(r=>[r.id,r.title]);
  if(!['select','status'].includes(type))options=[['','ยังไม่ระบุ'],...options];
  input=`<select name="${key}">${options.map(([v,l])=>option(v,l,value)).join('')}</select>`;
 }else input=`<input name="${key}" type="${type==='money'?'number':type}" ${type==='money'?'step="0.01" min="0"':''} value="${esc(value)}" ${key==='title'?'required maxlength="500"':''}>`;
 return `<label>${esc(label)}${input}</label>`;
 }).join('');const writable=p.role!=='VIEWER'&&!p.completed;modal(meta.label,`<fieldset ${writable?'':'disabled'}>${html}</fieldset>`,writable?d=>act('control',{...d,module,id}):null);}
function checklistForm(id){const p=pnow(),item=Object.values(p.lifecycleChecks).flat().find(i=>i.id===id),writable=p.role!=='VIEWER'&&!p.completed;modal(esc(item.title),`<fieldset ${writable?'':'disabled'}><p>${item.required?'รายการจำเป็น':'รายการแนะนำ'} · การยืนยันเสร็จต้องมีหลักฐานหรือเหตุผลที่ไม่เกี่ยวข้อง</p><label>สถานะ<select name="status">${state.statuses.map(s=>option(s,statusName[s],item.status||'TODO')).join('')}</select></label><label>ผู้รับผิดชอบ<select name="owner">${option('','ยังไม่มอบหมาย',item.owner)}${p.members.map(m=>option(m.user,m.user,item.owner)).join('')}</select></label><label>กำหนดเสร็จ<input name="due" type="date" value="${esc(item.due||'')}"></label><label>หลักฐาน / เหตุผลที่ไม่เกี่ยวข้อง<textarea name="evidence">${esc(item.evidence||'')}</textarea></label><label>รายละเอียด / รอใคร / ติดอะไร<textarea name="notes">${esc(item.notes||'')}</textarea></label></fieldset>`,writable?d=>saveInPlace('checklist',{...d,id}):null);}
function vendorContractSection(p){
 const rows=(p.controls?.procurement||[]).filter(r=>r.kind==='VENDOR_CONTRACT'),writable=p.role!=='VIEWER'&&!p.completed;
 return `<section class="card vendor-section"><div class="row"><div><span class="eyebrow">VENDOR CONTRACTS</span><h2>สัญญา Vendor <span class="section-count">${rows.length} สัญญา</span></h2></div>${writable?'<button type="button" data-add-vendor class="primary">+ เพิ่มสัญญา Vendor</button>':''}</div>${rows.length?`<div class="vendor-grid">${rows.map(r=>`<article class="vendor-box"><div class="row"><h3>${esc(r.vendor||r.title)}</h3><span class="checklist-status ${r.status==='BLOCKED'?'is-blocked':''}">${esc(statusName[r.status]||'ยังไม่เริ่ม')}</span></div><p>${esc(r.title)}</p><dl class="vendor-identifiers"><div><dt>เลขสัญญา</dt><dd>${esc(r.reference||'ยังไม่ระบุ')}</dd></div><div><dt>เลขของาน LSF</dt><dd>${esc(r.lsfNo||'ยังไม่ระบุ')}</dd></div></dl><p class="muted">${esc(r.startDate||'ยังไม่ระบุวันเริ่ม')} – ${esc(r.endDate||'ยังไม่ระบุวันสิ้นสุด')}</p><p class="muted">ผู้รับผิดชอบ: ${esc(r.owner||'ยังไม่มอบหมาย')}</p><button type="button" data-vendor-contract="${esc(r.id)}">${writable?'เปิด / แก้ไขสัญญา':'ดูสัญญา'}</button></article>`).join('')}</div>`:'<div class="vendor-empty">ยังไม่มีสัญญา Vendor <span>เพิ่มแยกได้หลายสัญญา ทั้ง Vendor เดิมและรายใหม่</span></div>'}</section>`;
}
function vendorContractForm(id){
 const p=pnow(),meta=state.controlModules.procurement,existing=(p.controls?.procurement||[]).find(r=>r.id===id),defaults=Object.fromEntries(meta.fields.map(([key,label,type,choices])=>[key,type==='select'?choices[0]:type==='status'?'TODO':''])),row={...defaults,...existing,kind:'VENDOR_CONTRACT'},writable=p.role!=='VIEWER'&&!p.completed;
 const fields=[['vendor','ชื่อ Vendor','text'],['title','ชื่อสัญญา / ขอบเขตงาน','text'],['reference','เลขสัญญา','text'],['lsfNo','เลขของาน LSF','text'],['startDate','วันเริ่มสัญญา','date'],['endDate','วันสิ้นสุดสัญญา','date'],['amount','มูลค่าสัญญา','number']];
 modal(id?'สัญญา Vendor':'เพิ่มสัญญา Vendor',`<fieldset ${writable?'':'disabled'}><div class="split">${fields.map(([key,label,type])=>`<label>${label}<input name="${key}" type="${type}" value="${esc(row[key]??'')}" ${['vendor','title'].includes(key)?'required maxlength="500"':''} ${key==='amount'?'min="0" step="0.01"':''}></label>`).join('')}<label>ผู้รับผิดชอบ<select name="owner">${option('','ยังไม่มอบหมาย',row.owner)}${p.members.map(m=>option(m.user,m.user,row.owner)).join('')}</select></label><label>สถานะ<select name="status">${state.statuses.map(s=>option(s,statusName[s],row.status)).join('')}</select></label><label>กำหนดติดตาม<input name="due" type="date" value="${esc(row.due)}"></label></div><label>หลักฐาน / ลิงก์สัญญา<textarea name="evidence">${esc(row.evidence)}</textarea></label><label>รายละเอียด / สิ่งที่รอ<textarea name="notes">${esc(row.notes)}</textarea></label><details><summary>ข้อมูลการจัดซื้อเพิ่มเติม</summary>${meta.fields.filter(([key])=>['poDate','period','completedDate','readiness','dependency','waitingFor'].includes(key)).map(([key,label,type,choices])=>`<label>${esc(label)}${type==='select'?`<select name="${key}">${choices.map(v=>option(v,kindLabels[v]||v,row[key])).join('')}</select>`:type==='textarea'?`<textarea name="${key}">${esc(row[key]||'')}</textarea>`:`<input name="${key}" type="${type}" value="${esc(row[key]||'')}">`}</label>`).join('')}</details></fieldset>${existing?commentsHtml(existing.comments||[]):''}${existing&&writable?'<button type="button" id="vendorComment">เพิ่มความคิดเห็น / @mention</button>':''}`,writable?d=>saveInPlace('control',{...row,...d,module:'procurement',id,kind:'VENDOR_CONTRACT'}):null);
 if($('#vendorComment'))$('#vendorComment').onclick=()=>commentForm('procurement',id);
}
function wireControls(){
 $$('[data-phase]',b=>b.onclick=()=>selectLifecyclePhase(b.dataset.phase));
 $$('[data-health-project]',b=>b.onclick=()=>openHealthTarget(b.dataset.healthProject).catch(e=>tell(e.message)));
 $$('[data-add-vendor]',b=>b.onclick=()=>vendorContractForm());
 $$('[data-vendor-contract]',b=>b.onclick=()=>vendorContractForm(b.dataset.vendorContract));
 $$('[data-add-control]',b=>b.onclick=()=>controlForm(b.dataset.addControl));
 $$('[data-edit-control]',b=>b.onclick=()=>controlForm(b.dataset.module,b.dataset.editControl));
 $$('[data-check]',b=>b.onclick=()=>checklistForm(b.dataset.check));
 $$('[data-detail-milestone]',b=>b.onclick=()=>milestoneDetail(b.dataset.detailMilestone));
 $$('[data-record-comment]',b=>b.onclick=()=>commentForm(b.dataset.module,b.dataset.recordComment));
 $$('[data-my-control]',b=>b.onclick=()=>{selected=b.dataset.project;controlForm(b.dataset.module,b.dataset.myControl)});
 $$('[data-my-check]',b=>b.onclick=()=>{selected=b.dataset.project;if(pnow().role==='VIEWER'||pnow().completed){view='lifecycle';render()}else checklistForm(b.dataset.myCheck)});
 $$('[data-my-milestone]',b=>b.onclick=()=>{selected=b.dataset.project;milestoneDetail(b.dataset.myMilestone)});
 if($('#addPlanningTask'))$('#addPlanningTask').onclick=()=>taskForm();
 if($('#addPlanningMilestone'))$('#addPlanningMilestone').onclick=()=>act('milestone_add',{});
 if($('#renameHeaders'))$('#renameHeaders').onclick=()=>{const p=pnow(),labels=p.milestoneLabels||{};modal('แก้ชื่อหัวตาราง',torCols.map(f=>`<label>${esc(labels[f]||f)}<input name="${f}" value="${esc(labels[f]||f)}" required maxlength="200"></label>`).join(''),async d=>{const changes=torCols.filter(f=>d[f]!==labels[f]).map(field=>({field,label:d[field]}));if(changes.length)await api('action',{action:'milestone_headers',project:selected,labels:changes});await refresh();selected=p.id;view='tor';render()})};
}

function commentsHtml(comments=[]){return comments.map(c=>`<div class="timeline"><strong>${esc(c.author)}</strong><small> · ${esc(new Date(c.at).toLocaleString('th-TH'))}</small><p>${esc(c.text)}</p></div>`).join('')}
function commentForm(targetType,id){modal('ความคิดเห็น / @mention','<label>ข้อความ<textarea name="text" required maxlength="4000"></textarea></label>',d=>act('comment',{...d,targetType,id}))}
function milestoneDetail(id){const p=pnow(),m=p.milestones.find(x=>x.id===id),writable=p.role!=='VIEWER'&&!p.completed;
 const history=p.events.filter(e=>{try{return JSON.parse(e.detail).id===id}catch{return false}});
 const linked=(p.controls?.documents||[]).filter(r=>r.relatedId===id);
 modal('งวดงานที่ '+esc(m.workNo),`<h3>สิ่งส่งมอบ</h3><pre>${esc(m.deliverables)}</pre><h3>ขอบเขตของงาน</h3><pre>${esc(m.scope)}</pre><fieldset ${writable?'':'disabled'}><label>สถานะ<select name="status">${state.milestoneStatuses.map(s=>option(s,milestoneStatusName[s],m.status)).join('')}</select></label><label>ผู้รับผิดชอบ<select name="owner">${option('','ยังไม่มอบหมาย',m.owner)}${p.members.map(x=>option(x.user,x.user,m.owner)).join('')}</select></label><label>ขั้นตอนถัดไป<textarea name="next">${esc(m.next||'')}</textarea></label><label>ติดอะไร / รอใคร<textarea name="waiting">${esc(m.waiting||'')}</textarea></label><label>บันทึกส่งต่อ / ทำแล้ว / คงเหลือ<textarea name="handover">${esc(m.handover||'')}</textarea></label><label>หลักฐาน / เอกสาร<textarea name="evidence">${esc(m.evidence||'')}</textarea></label></fieldset><h3>เอกสารที่ผูกไว้</h3>${linked.map(r=>`<p>${esc(r.title)} · ${esc(r.evidence)}</p>`).join('')||'<p>ยังไม่มีเอกสารที่ผูกไว้</p>'}<h3>ความคิดเห็น</h3>${commentsHtml(m.comments)}${writable?'<button type="button" id="milestoneComment">เพิ่มความคิดเห็น / @mention</button>':''}<h3>ประวัติงวดงาน</h3>${history.slice(0,30).map(e=>`<div class="timeline"><strong>${esc(e.actor)}</strong> · ${esc(new Date(e.at).toLocaleString('th-TH'))}<p>${esc(e.action==='milestone_details'?'แก้สถานะ / ผู้รับผิดชอบ / การส่งต่อ':eventSummary(e))}</p></div>`).join('')}`,writable?d=>act('milestone_details',{...d,id}):null);
 if($('#milestoneComment'))$('#milestoneComment').onclick=()=>commentForm('milestone',id);
}
async function pasteTorCells(event,el){const text=event.clipboardData?.getData('text/plain')||'';if(!text.includes('\t'))return;
 event.preventDefault();await cellSaves;
 const p=pnow(),startRow=p.milestones.findIndex(m=>m.id===el.dataset.mid),startCol=torCols.indexOf(el.dataset.field);
 const rows=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(line=>line.split('\t'));
 if(startRow+rows.length>p.milestones.length||rows.some(r=>startCol+r.length>torCols.length)){tell('ข้อมูลเกินขอบตาราง กรุณาเพิ่มงวดงานหรือเลือกช่องเริ่มต้นใหม่');return}
 const cells=rows.flatMap((r,ri)=>r.map((value,ci)=>({id:p.milestones[startRow+ri].id,field:torCols[startCol+ci],value})));
 for(const c of cells)cellDrafts.set(draftKey(selected,c.id,c.field),c.value);
 tell('กำลังบันทึกข้อมูลหลายช่อง…');
 try{await api('action',{action:'milestone_cells',project:selected,cells});for(const c of cells)cellDrafts.delete(draftKey(selected,c.id,c.field));await refresh();tell('บันทึกข้อมูลหลายช่องแล้ว')}
 catch(e){render();tell(e.message+' · ยังไม่บันทึก เก็บค่าที่วางไว้ให้แก้ไขแล้ว')}
}
function teamView(p){const h=p.handoverDetails||{},cr=p.crisis||{},writable=p.role!=='VIEWER'&&!p.completed,canAccept=cr.active&&cr.actingOwner===state.user&&!cr.acceptedAt;return `<section class="card row"><div><h2>สมาชิกโครงการ</h2><p class="muted">OWNER จัดการทุก role; EDITOR เพิ่มสมาชิกใหม่เป็น EDITOR หรือ VIEWER</p></div>${['OWNER','EDITOR'].includes(p.role)?'<button id="addMember" class="primary">เพิ่มสมาชิก</button>':''}</section><section class="card">${p.members.map(m=>`<div class="task"><div><h3>${esc(m.user)}</h3><small>เพิ่มโดย ${esc(m.addedBy)} · ให้สิทธิ์โดย ${esc(m.grantedBy)}</small></div><div>${badge(m.role)} ${p.role==='OWNER'?`<button data-member="${esc(m.user)}">จัดการ</button>`:''}</div></div>`).join('')}</section>
<section class="card"><div class="row"><div><span class="eyebrow">CRISIS / EMERGENCY HANDOVER</span><h2>${cr.active?'กำลังส่งต่องานฉุกเฉิน':'โหมดปกติ'}</h2><p class="muted">${cr.active?'ให้ผู้รับช่วงเห็นสิ่งที่ต้องทำต่อและ dependency สำคัญในหน้าเดียว':'เปิดใช้เมื่อเจ้าของโครงการไม่สามารถถือโครงการต่อได้ชั่วคราว'}</p></div><div class="row">${cr.active?badge('BLOCKED'):badge('DONE')}${writable?`<button id="crisisHandover">${cr.active?'อัปเดต Crisis':'เปิด Crisis Handover'}</button>`:''}${canAccept?'<button id="acceptCrisis" class="primary">รับช่วงงาน</button>':''}</div></div>${cr.active?`<div class="contract-grid">${infoCell('เจ้าของงานเดิม',cr.originalOwner||'—')}${infoCell('ผู้รับช่วง',cr.actingOwner||'—')}${infoCell('สถานะการรับช่วง',cr.acceptedAt?'รับช่วงแล้ว '+new Date(cr.acceptedAt).toLocaleString('th-TH'):'รอผู้รับช่วงกดยืนยัน')}${infoCell('เหตุผล',cr.reason||'—')}${infoCell('Critical Next Actions',cr.criticalNextActions||'—')}${infoCell('Dependency / กำลังรอ',cr.waiting||'—')}${infoCell('ผู้ติดต่อสำคัญ',cr.contacts||'—')}${infoCell('การสื่อสารล่าสุด',cr.latestCommunication||'—')}${infoCell('เอกสาร / ลิงก์สำคัญ',cr.links||'—')}</div>`:'<p class="empty">ยังไม่ได้เปิด Crisis Handover</p>'}</section>
<section class="card"><div class="row"><div><h2>ส่งต่องาน</h2><p class="muted">บันทึกสิ่งที่ผู้รับช่วงต้องรู้ เพื่อให้ทำงานต่อได้ทันที</p></div>${writable?'<button id="handover">อัปเดต</button>':''}</div><div class="contract-grid">${infoCell('สถานะปัจจุบัน',h.status||'ยังไม่บันทึก')}${infoCell('ทำแล้ว',h.done||'—')}${infoCell('สิ่งที่เหลือ',h.remaining||'—')}${infoCell('ขั้นตอนถัดไป',h.next||'—')}${infoCell('รอใคร / อะไร',h.waiting||'—')}${infoCell('ลิงก์ / เอกสารสำคัญ',h.links||p.handover||'—')}</div></section>`}
function handoverForm(){const p=pnow(),h=p.handoverDetails||{};modal('บันทึกส่งต่องาน',`<label>สถานะปัจจุบัน<textarea name="status">${esc(h.status||'')}</textarea></label><label>ทำอะไรแล้ว<textarea name="done">${esc(h.done||'')}</textarea></label><label>สิ่งที่ยังเหลือ<textarea name="remaining">${esc(h.remaining||'')}</textarea></label><label>ขั้นตอนถัดไป<textarea name="next">${esc(h.next||'')}</textarea></label><label>กำลังรอใคร / อะไร<textarea name="waiting">${esc(h.waiting||'')}</textarea></label><label>ลิงก์ / เอกสารสำคัญ<textarea name="links">${esc(h.links||p.handover||'')}</textarea></label>`,d=>act('handover',{details:d}))}
function crisisHandoverForm(){const p=pnow(),cr=p.crisis||{},memberOptions=p.members.map(m=>option(m.user,m.user,'')).join('');modal(cr.active?'อัปเดต Crisis Handover':'เปิด Crisis Handover',`<label class="check"><input type="checkbox" name="active" ${cr.active?'checked':''}> เปิด Crisis / Emergency Handover</label><label>เจ้าของงานเดิม<select name="originalOwner"><option value="">— เลือก —</option>${p.members.map(m=>option(m.user,m.user,cr.originalOwner)).join('')}</select></label><label>ผู้รับช่วง<select name="actingOwner"><option value="">— เลือก —</option>${p.members.map(m=>option(m.user,m.user,cr.actingOwner)).join('')}</select></label><label>เหตุผลที่ต้องส่งต่องานฉุกเฉิน<textarea name="reason" maxlength="4000">${esc(cr.reason||'')}</textarea></label><label>Critical Next Actions<textarea name="criticalNextActions" maxlength="4000" placeholder="งานที่ต้องทำต่อทันที / deadline / owner">${esc(cr.criticalNextActions||'')}</textarea></label><label>Dependency / กำลังรอใครหรืออะไร<textarea name="waiting" maxlength="4000">${esc(cr.waiting||'')}</textarea></label><label>ผู้ติดต่อสำคัญ<textarea name="contacts" maxlength="4000">${esc(cr.contacts||'')}</textarea></label><label>การสื่อสารล่าสุด<textarea name="latestCommunication" maxlength="4000">${esc(cr.latestCommunication||'')}</textarea></label><label>เอกสาร / ลิงก์สำคัญ<textarea name="links" maxlength="4000">${esc(cr.links||'')}</textarea></label>`,d=>act('crisis_handover',{...d,active:d.active==='on'}))}
function myWorkView(){return state.projects.map(p=>{
 const records=Object.entries(p.controls||{}).flatMap(([module,rows])=>rows.filter(r=>r.owner===state.user&&r.status!=='DONE').map(r=>`<div class="task"><div><strong>${esc(r.title)}</strong><p>${esc(statusName[r.status])} · ${esc(r.due||'ไม่ระบุวัน')} · ${esc(state.controlModules[module].label)}</p></div><button data-my-control="${r.id}" data-module="${module}" data-project="${p.id}">เปิดรายการ</button></div>`));
 const checks=Object.values(p.lifecycleChecks||{}).flat().filter(c=>c.owner===state.user&&c.status!=='DONE').map(c=>`<div class="task"><strong>${esc(c.title)}</strong><button data-my-check="${c.id}" data-project="${p.id}">เปิด Checklist</button></div>`);
 const milestones=p.milestones.filter(m=>m.owner===state.user&&!['DELIVERED','WAITING_REPLY','WAITING_ACCEPTANCE','ACCEPTED'].includes(m.status)).map(m=>`<div class="task"><strong>งวด ${esc(m.workNo)} · ${esc(m.next||'ยังไม่ระบุขั้นตอนถัดไป')}</strong><button data-my-milestone="${m.id}" data-project="${p.id}">เปิดงวดงาน</button></div>`);
 return `<section class="card"><h2>${esc(p.name)}</h2>${tasksHtml(p.tasks.filter(t=>(t.owner===state.user||t.backupOwner===state.user)&&t.status!=='DONE'),p)}${records.join('')}${checks.join('')}${milestones.join('')}</section>`;
 }).join('')||'<section class="card">ยังไม่มีโครงการ</section>'}
function homeView(p){
  const crisis=p.crisis||{};
  const d=p.deliverySummary||{total:0,done:0,accepted:0,percent:0},c=p.controlSummary||{alerts:[],openRisks:0},current=d.current;
  const next=(p.milestones||[]).find(m=>!['DELIVERED','WAITING_REPLY','WAITING_ACCEPTANCE','ACCEPTED'].includes(m.status)&&m.id!==current?.id);
  const pending=[...(c.alerts||[]),...(p.controls?.risk||[]).filter(r=>r.status!=='DONE').map(r=>({title:`${kindLabels[r.recordType]||'ความเสี่ยง'}: ${r.title}`,module:'risk'})),...(current&&['BLOCKED','WAITING_REPLY','WAITING_ACCEPTANCE'].includes(current.status)?[{title:`งวด ${current.workNo}: ${current.waiting||milestoneStatusName[current.status]}`,module:'tor'}]:[]),...(p.tasks||[]).filter(t=>['WAITING','BLOCKED'].includes(t.status)).map(t=>({title:`งาน ${t.status==='BLOCKED'?'ติดปัญหา':'รอการตอบกลับ'}: ${t.title}`,module:'tasks'}))].filter((x,i,a)=>a.findIndex(y=>y.module===x.module&&y.title===x.title)===i).slice(0,4);
  return `${crisis.active?`<section class="card"><div class="row"><div><span class="eyebrow">CRISIS HANDOVER ACTIVE</span><h2>ผู้รับช่วง: ${esc(crisis.actingOwner||'ยังไม่ระบุ')}</h2><p>${esc(crisis.reason||'')}</p><p class="muted">Critical Next Actions: ${esc(crisis.criticalNextActions||'ยังไม่ระบุ')} · รอ: ${esc(crisis.waiting||'—')}</p></div><button data-view="team">เปิด Crisis Handover</button></div></section>`:''}<section class="command-hero"><div><span class="eyebrow">PROJECT OVERVIEW</span><h2>${esc(p.name)}</h2><p class="muted">${esc(p.projectInfo?.projectCode||'ยังไม่มี Project Code')} · ${esc(phaseName(p.phase))} · ${healthLink(p)}</p><p class="muted">${esc(p.health?.reason||'')}</p></div>${p.role==='OWNER'?'<button id="settings">ตั้งค่าโครงการ</button>':''}</section>
  <div class="command-grid"><section class="metric command-main"><span>ส่งมอบแล้ว</span><strong>${d.done||0} / ${d.total||0} งวด · ${num(d.percent)}%</strong><progress value="${d.done||0}" max="${d.total||1}"></progress></section><section class="metric"><span>ตรวจรับแล้ว</span><strong>${d.accepted||0} / ${d.total||0} งวด</strong></section><section class="metric"><span>Current</span><strong>${current?'งวดงานที่ '+esc(current.workNo):'ไม่มีงวดค้าง'}</strong><small>${esc(milestoneStatusName[current?.status]||'')}</small></section><section class="metric"><span>Next</span><strong>${next?'งวดงานที่ '+esc(next.workNo):'—'}</strong><small>กำหนดตามแผน ${esc(next?.planDue||'ยังไม่กำหนด')}</small></section></div>
  <div class="grid command-columns"><section class="card"><div class="row"><h2>งวดปัจจุบัน</h2><button data-view="tor">เปิด TOR / ส่งมอบ</button></div>${current?`<h3>งวดงานที่ ${esc(current.workNo)} · ${esc((current.deliverables||'').split('\n')[0])}</h3><p>${esc(milestoneStatusName[current.status]||'ยังไม่ระบุ')} · ผู้รับผิดชอบ ${esc(current.owner||'ยังไม่มอบหมาย')}</p><p>ขั้นตอนถัดไป: ${esc(current.next||'บันทึกผู้รับผิดชอบ ขั้นตอนถัดไป และหลักฐาน')}</p>`:'<p class="empty">ไม่มีงวดงานที่กำลังดำเนินการ</p>'}</section><section class="card"><div class="row"><h2>ต้องติดตาม · ${pending.length}</h2><button data-view="risk">ดู Risk / Issue</button></div>${pending.map(a=>`<div class="task"><span>${esc(a.title)}</span><button data-view="${esc(a.module)}">เปิด</button></div>`).join('')||'<p class="empty">ยังไม่มีรายการเร่งติดตาม</p>'}</section></div>
  <section class="card"><div class="row"><h2>ความเคลื่อนไหวล่าสุด</h2><button data-view="team">ส่งต่องาน / ทีม</button></div>${(p.events||[]).slice(0,5).map(e=>`<div class="timeline"><strong>${esc(e.actor)}</strong><small> · ${esc(new Date(e.at).toLocaleString('th-TH'))}</small><p>${esc(eventSummary(e))}</p></div>`).join('')||'<p class="empty">ยังไม่มี activity</p>'}</section>`
}
refresh();
